 59	  private constructor(executable: string, private readonly options: NativeTransportOptions) {
 60	    this.gate = new FilesystemCommandGate({ session: this.session, generation: options.generation })
 61	    this.child = spawn(executable, [], { windowsHide: true, stdio: 'pipe', shell: false })
