101	  }
102	  request(payload: FilesystemPayload): Promise<Reply> {
103	    if (this.unusable) return Promise.reject(new FilesystemTransportError('REFUSED', 'FILESYSTEM_SESSION_CLOSED'))
104	    if (this.pending) { this.fail('CONCURRENT_FILESYSTEM_COMMAND'); return Promise.reject(new FilesystemTransportError('REFUSED', 'CONCURRENT_FILESYSTEM_COMMAND')) }
105	    const now = this.nextId === 1 ? 0 : Math.floor(this.helperClock + Math.max(0, performance.now() - this.receivedAt))
106	    const command = { version: 1, session: this.session, generation: this.options.generation, requestId: this.nextId, deadlineMs: now + MAX_OPERATION_MS, ...payload }
107	    const frame = Buffer.from(JSON.stringify(command) + '\n')
108	    const accepted = this.gate.accept(frame, now)
109	    if (!accepted) { this.fail('INVALID_FILESYSTEM_COMMAND'); return Promise.reject(new FilesystemTransportError('REFUSED', 'INVALID_FILESYSTEM_COMMAND')) }
