115	  private reply(chunk: Buffer) {
116	    if (!this.pending || this.bytes.length + chunk.length > MAX_FRAME_BYTES) { this.fail('INVALID_FILESYSTEM_REPLY'); return }
117	    this.bytes = Buffer.concat([this.bytes, chunk])
118	    const newline = this.bytes.indexOf(10)
119	    if (newline < 0) return
120	    const pending = this.pending
121	    try {
122	      if (newline !== this.bytes.length - 1) throw Error('MULTIPLE_REPLY_FRAMES')
123	      const bodyEnd = newline > 0 && this.bytes[newline - 1] === 13 ? newline - 1 : newline
