134	      pending.resolve(reply)
135	    } catch { this.fail('INVALID_FILESYSTEM_REPLY') }
136	  }
137	  dispose(): Promise<void> {
138	    return this.disposal ??= (async () => {
139	      let failure: unknown
140	      try {
141	        if (!this.unusable && !this.pending) await this.request({ operation: 'dispose' })
142	        else this.fail('FILESYSTEM_SESSION_CLOSED')
143	      } catch (error) { failure = error; this.fail('FILESYSTEM_SESSION_CLOSED') }
