145	      try {
146	        await Promise.race([this.exit, new Promise<never>((_resolve, reject) => {
147	          timer = setTimeout(() => reject(new FilesystemTransportError('UNKNOWN', 'FILESYSTEM_CLOSE_UNCONFIRMED')), MAX_OPERATION_MS)
148	        })])
149	      } finally { clearTimeout(timer) }
150	      if (failure) throw failure
151	    })()
152	  }
153	}

