10	type Readiness = Readonly<{ state: 'BACKEND_VERIFIED'; installer: 'NOT_IMPLEMENTED' } | { state: 'UNAVAILABLE'; code: string }>
11	/** Read-only absence diagnostic, never a filesystem backend or write authorization. */
12	async function rootAbsent(root: string) {
13	  try { await fs.lstat(root); return false } catch (error) {
14	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return true
