18	/** Main-only S1 owner. Installed or ambiguous state remains blocked until the P02 coordinator exists. */
19	export class ExtensionInstallerHost {
20	  private initializing: Promise<Readiness> | undefined
21	  private disposing: Promise<void> | undefined
22	  private closing = false
23	  private generation = 1
24	  private context: VerifiedFilesystem | undefined
25	  private contextDisposal: Promise<void> | undefined
26	  constructor(private readonly userData: string, private readonly distributionDirectory: string, private readonly ports: Ports = {}) {}
27	  initialize(): Promise<Readiness> {
28	    if (this.closing) return Promise.reject(Error('EXTENSION_HOST_CLOSED'))
29	    return this.initializing ??= this.open()
30	  }
31	  private async open(): Promise<Readiness> {
32	    const generation = this.generation, installationRoot = join(this.userData, 'extensions')
33	    try {
34	      const context = await (this.ports.open ?? createVerifiedFilesystem)({ installationRoot, distributionDirectory: this.distributionDirectory, sourceSha256: NATIVE_FILESYSTEM_SOURCE_SHA256, generation })
35	      this.context = context
36	      if (this.closing || generation !== this.generation) { await this.closeContext(); throw Error('EXTENSION_HOST_CLOSED') }
37	      if (context.state !== 'VERIFIED' || context.rootEntries.some(entry => entry.name !== '.coordinator.lock')) {
38	        await this.closeContext(); throw Error('EXTENSION_RECOVERY_REQUIRED')
39	      }
40	      return Object.freeze({ state: 'BACKEND_VERIFIED', installer: 'NOT_IMPLEMENTED' })
41	    } catch (error) {
42	      if (this.closing || generation !== this.generation) throw error
43	      // Only a pre-effect typed unavailable backend + absent root permits built-ins.
44	      // A present/unsafe/unreadable root or possible-effect UNKNOWN never falls back.
45	      if (error instanceof Error && Reflect.get(error, 'status') === 'BACKEND_UNAVAILABLE' && await (this.ports.rootAbsent ?? rootAbsent)(installationRoot))
46	        return Object.freeze({ state: 'UNAVAILABLE', code: error.message })
47	      throw error
48	    }
49	  }
50	  private closeContext(): Promise<void> {
51	    return this.context ? this.contextDisposal ??= this.context.dispose() : Promise.resolve()
52	  }
53	  dispose(): Promise<void> {
54	    if (this.disposing) return this.disposing
55	    this.closing = true; this.generation++
56	    return this.disposing = (async () => {
57	      if (this.initializing) { try { await this.initializing } catch (error) {
58	        if (!this.context && error instanceof Error && error.message === 'FILESYSTEM_CLOSE_UNCONFIRMED') throw error
59	      } }
60	      await this.closeContext()
61	    })()
62	  }
63	}

